  const { t: translate } = useTranslation("common");

  if (navItems.length === 0) {
    return undefined;
  }

  // Items with `nav_top_level` set are always promoted directly onto the toolbar.
  const promotedItems: Array<NavItemResponse> = [];
  const nonPromotedItems: Array<NavItemResponse> = [];

